"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["1281"],{3813(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"phenolab-beta-release","metadata":{"permalink":"/phenolab-web/blog/phenolab-beta-release","editUrl":"https://github.com/OpenSciML/phenolab-web/tree/main/blog/2026-09-03-phenolab-beta-release.md","source":"@site/blog/2026-09-03-phenolab-beta-release.md","title":"PhenoLab Beta Is Here","description":"We are excited to share the beta release of PhenoLab, a crop phenotyping web platform for organizing field studies, managing plot-level research assets, running reusable analysis workflows, and turning experimental data into research-ready outputs.","date":"2026-09-03T00:00:00.000Z","tags":[{"inline":false,"label":"Release notes","permalink":"/phenolab-web/blog/tags/release-notes","description":"PhenoLab release notes and version updates."},{"inline":false,"label":"Development","permalink":"/phenolab-web/blog/tags/development","description":"Engineering and product development updates."}],"readingTime":1.17,"hasTruncateMarker":true,"authors":[{"name":"PhenoLab Contributors","title":"PhenoLab Project Team","url":"https://github.com/OpenSciML/phenolab","imageURL":"/phenolab-web/img/phenolab-logo.png","key":"phenolab","page":null}],"frontMatter":{"slug":"phenolab-beta-release","title":"PhenoLab Beta Is Here","authors":["phenolab"],"tags":["release-notes","development"]},"unlisted":false,"nextItem":{"title":"PhenoLab Documentation Moves to Docusaurus","permalink":"/phenolab-web/blog/website-docs-migration"}},"content":"We are excited to share the beta release of PhenoLab, a crop phenotyping web platform for organizing field studies, managing plot-level research assets, running reusable analysis workflows, and turning experimental data into research-ready outputs.\\n\\n{/* truncate */}\\n\\nThis beta brings the main pieces of the PhenoLab workflow together in one browser-based workspace:\\n\\n- **Project and study organization** for structuring research work across projects, studies, datasets, plots, and assets.\\n- **Dataset editing tools** for registering plot-level imagery, sensor data, metadata, treatments, and supporting files.\\n- **Reusable LgoPy analysis modules** that can be installed, searched, inspected, and combined like building blocks for phenotyping and remote-sensing workflows.\\n- **Analysis pipelines** for running dataset-level workflows, tracking progress, reviewing logs, and collecting generated artifacts.\\n- **Results and exports** that keep derived files, figures, tables, metadata, and pipeline outputs connected to the original study context.\\n- **Configuration and deployment documentation** for running PhenoLab locally today while keeping a clear path toward hosted deployments.\\n\\nThe beta also introduces the direction for PhenoLab\'s scientific knowledge base and agent-assisted workflows. The goal is to help research teams move from multimodal field observations to defensible findings, downstream analysis, scientific discovery, manuscripts, and grant proposals while keeping methods, provenance, and outputs organized.\\n\\nThis release is an important step toward a more modular, reusable, and transparent phenotyping platform. We will use this blog to share updates, release notes, tutorials, and development progress as PhenoLab continues to evolve."},{"id":"website-docs-migration","metadata":{"permalink":"/phenolab-web/blog/website-docs-migration","editUrl":"https://github.com/OpenSciML/phenolab-web/tree/main/blog/2026-09-03-website-docs-migration.md","source":"@site/blog/2026-09-03-website-docs-migration.md","title":"PhenoLab Documentation Moves to Docusaurus","description":"The PhenoLab website now uses Docusaurus for documentation, project updates,","date":"2026-09-03T00:00:00.000Z","tags":[{"inline":false,"label":"Documentation","permalink":"/phenolab-web/blog/tags/documentation","description":"Documentation and website updates."},{"inline":false,"label":"Development","permalink":"/phenolab-web/blog/tags/development","description":"Engineering and product development updates."}],"readingTime":0.32,"hasTruncateMarker":true,"authors":[{"name":"PhenoLab Contributors","title":"PhenoLab Project Team","url":"https://github.com/OpenSciML/phenolab","imageURL":"/phenolab-web/img/phenolab-logo.png","key":"phenolab","page":null}],"frontMatter":{"slug":"website-docs-migration","title":"PhenoLab Documentation Moves to Docusaurus","authors":["phenolab"],"tags":["documentation","development"]},"unlisted":false,"prevItem":{"title":"PhenoLab Beta Is Here","permalink":"/phenolab-web/blog/phenolab-beta-release"}},"content":"The PhenoLab website now uses Docusaurus for documentation, project updates,\\nrelease notes, and development notes.\\n\\n{/* truncate */}\\n\\nThe initial documentation content was migrated from the existing MkDocs source\\ntree and keeps the same major sections: getting started, software overview,\\nfeatures, tutorials, deployment, FAQ, and troubleshooting.\\n\\nFuture updates can be published here as blog posts while the docs remain focused\\non stable user and developer guidance."}]}}')}}]);